from collections import deque

def find_connected_components_with_sizes(grid, rows, cols):
    """Return list of (component_cells, component_size, center_val)"""
    visited = set()
    components = []

    for i in range(rows):
        for j in range(cols):
            if (i,j) not in visited:
                # Get value at this position
                val = grid[i][j]

                if val == 0:
                    continue

                component = []
                queue = deque([(i,j)])
                visited.add((i,j))

                while queue:
                    r, c = queue.popleft()
                    component.append((r,c))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == val and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                queue.append((nr,nc))
                components.append((component, len(component), val))

    return components

